#!/usr/bin/env python3
"""Select the boot-v2 fallback or experimental vendor-boot-v3 build layout."""
import argparse
import pathlib

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('layout', choices=('boot-v2', 'vendor-boot-v3'))
args = parser.parse_args()
tree = pathlib.Path(__file__).resolve().parents[1]
(tree / 'recovery-layout.mk').write_text(
    '# Generated by tools/select-layout.py\n'
    f'include $(DEVICE_PATH)/profiles/{args.layout}.mk\n'
)
print('Selected recovery layout:', args.layout)
